package ec.edu.ucacue.odontocare.treatment.domain;
import java.util.*;import ec.edu.ucacue.odontocare.clinicalrecord.domain.ClinicalRecord;import jakarta.persistence.*;
@Entity @Table(name="treatment_plans") public class TreatmentPlan{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="clinical_record_id")private ClinicalRecord clinicalRecord;private String title;private String status;@Column(name="created_by")private Long createdBy;@OneToMany(mappedBy="plan",cascade=CascadeType.ALL)@OrderBy("priority ASC, id ASC")private List<TreatmentPlanItem> items=new ArrayList<>();protected TreatmentPlan(){}public TreatmentPlan(ClinicalRecord r,String title,Long user){clinicalRecord=r;this.title=title;status="ACTIVE";createdBy=user;}public void add(TreatmentPlanItem i){items.add(i);}public Long getId(){return id;}public String getTitle(){return title;}public String getStatus(){return status;}public List<TreatmentPlanItem> getItems(){return items;}}
